#include <iostream>
#include <algorithm>
using namespace std;

class Buffer {
    int* data;
    size_t size;
public:
    Buffer(size_t s) : size(s) { data = new int[s]; fill(data, data+s, 0); cout << "Constructed\n"; }
    ~Buffer() { delete[] data; cout << "Destroyed\n"; }
    Buffer(const Buffer& other) : size(other.size) { data = new int[size]; copy(other.data, other.data+size, data); cout << "Copied\n"; }
    Buffer(Buffer&& other) : data(other.data), size(other.size) {
        other.data = nullptr; other.size = 0;
        cout << "Moved\n";
    }
    size_t getSize() const { return size; }
};

int main() {
    Buffer b1(100);
    Buffer b2 = move(b1);
    cout << "b1 size: " << b1.getSize() << ", b2 size: " << b2.getSize() << endl;
    return 0;
}
